DROP POLICY "agents_tenant" ON "agents";--> statement-breakpoint
CREATE POLICY "agents_read" ON "agents" AS PERMISSIVE FOR SELECT TO public USING ("agents"."organization_id" = nullif(current_setting('app.organization_id', true), '')::uuid AND (nullif(current_setting('app.user_id', true), '')::uuid IS NULL OR "agents"."created_by" = nullif(current_setting('app.user_id', true), '')::uuid OR snowfall_is_admin() OR snowfall_access('agent', "agents"."id") IS NOT NULL));--> statement-breakpoint
CREATE POLICY "agents_insert" ON "agents" AS PERMISSIVE FOR INSERT TO public WITH CHECK ("agents"."organization_id" = nullif(current_setting('app.organization_id', true), '')::uuid);--> statement-breakpoint
CREATE POLICY "agents_update" ON "agents" AS PERMISSIVE FOR UPDATE TO public USING ("agents"."organization_id" = nullif(current_setting('app.organization_id', true), '')::uuid) WITH CHECK ("agents"."organization_id" = nullif(current_setting('app.organization_id', true), '')::uuid);--> statement-breakpoint
CREATE POLICY "agents_delete" ON "agents" AS PERMISSIVE FOR DELETE TO public USING ("agents"."organization_id" = nullif(current_setting('app.organization_id', true), '')::uuid);--> statement-breakpoint
CREATE POLICY "prompts_editor_update" ON "prompts" AS PERMISSIVE FOR UPDATE TO public USING ("prompts"."organization_id" = nullif(current_setting('app.organization_id', true), '')::uuid AND snowfall_access('prompt', "prompts"."id") = 'edit') WITH CHECK ("prompts"."organization_id" = nullif(current_setting('app.organization_id', true), '')::uuid);--> statement-breakpoint
ALTER POLICY "prompts_read" ON "prompts" TO public USING ("prompts"."organization_id" = nullif(current_setting('app.organization_id', true), '')::uuid AND ("prompts"."user_id" = nullif(current_setting('app.user_id', true), '')::uuid OR snowfall_access('prompt', "prompts"."id") IS NOT NULL));--> statement-breakpoint
-- Après la nouvelle politique de lecture (l'ancienne dépendait de cette colonne).
ALTER TABLE "prompts" DROP COLUMN "shared";
